local NYXO_REDRUM_URL = "https://file.garden/algLafWA1jk8WMfK/redrum_spotdown.org%202.mp3"
local NYXO_REDRUM_FILE = "nyxo_redrum.mp3"
local nyxoRedrumAsset = nil
local nyxoFullRedrumSound = nil
local nyxoMusicRequest = 0
local nyxoMusicRefreshers = {}

local function getNYXORedrumAsset()
    if nyxoRedrumAsset then return nyxoRedrumAsset end

    local assetLoader = getcustomasset or getsynasset
    if type(assetLoader) ~= "function" or type(writefile) ~= "function" then
        return nil, "custom asset functions unavailable"
    end

    local exists = false
    if type(isfile) == "function" then
        local okExists, result = pcall(isfile, NYXO_REDRUM_FILE)
        exists = okExists and result == true
    end

    if not exists then
        local okDownload, data = pcall(function()
            return game:HttpGet(NYXO_REDRUM_URL)
        end)
        if not okDownload or type(data) ~= "string" or #data < 256 then
            return nil, "could not download redrum"
        end

        local okWrite = pcall(writefile, NYXO_REDRUM_FILE, data)
        if not okWrite then
            return nil, "could not save redrum"
        end
    end

    local okAsset, asset = pcall(assetLoader, NYXO_REDRUM_FILE)
    if not okAsset or type(asset) ~= "string" or asset == "" then
        return nil, "could not create redrum asset"
    end

    nyxoRedrumAsset = asset
    return asset
end

local function makeNYXORedrumSound(startAt, name)
    local asset, err = getNYXORedrumAsset()
    if not asset then
        warn("[NYXO Music] " .. tostring(err))
        return nil
    end

    local sound = Instance.new("Sound")
    sound.Name = name or "NYXORedrum"
    sound.SoundId = asset
    sound.Volume = 1
    sound.Looped = false
    sound.Parent = SoundService

    local startPosition = math.max(0, tonumber(startAt) or 0)
    pcall(function() sound.TimePosition = startPosition end)
    pcall(function() sound:Play() end)

    task.spawn(function()
        local startedWaiting = tick()
        while sound.Parent and not sound.IsLoaded and tick() - startedWaiting < 8 do
            task.wait(0.05)
        end
        if sound.Parent then
            pcall(function()
                sound.TimePosition = startPosition
                if not sound.Playing then sound:Play() end
            end)
        end
    end)

    return sound
end

local function stopNYXOFullRedrum()
    nyxoMusicRequest = nyxoMusicRequest + 1
    if nyxoFullRedrumSound then
        pcall(function() nyxoFullRedrumSound:Stop() end)
        pcall(function() nyxoFullRedrumSound:Destroy() end)
        nyxoFullRedrumSound = nil
    end
end


