local function scheduleNYXOHUBSave(delaySeconds)
    if _nyxoHubSaveState.queued then return end
    _nyxoHubSaveState.queued = true
    task.delay(delaySeconds or 0.25, function()
        _nyxoHubSaveState.queued = false
        if _G.NYXOHUBRunning and not _isResetting and not _isLoading then
            pcall(saveAllSettings, true)
        end
    end)
end

function saveAllSettings(force)
    if _isResetting or _isLoading then return true end

    local config = buildConfigTable()
    config.configVersion = 2
    config.userId = LP.UserId
    local encodedOk, canonicalJSON = pcall(function() return HS:JSONEncode(config) end)
    if not encodedOk then
        warn("[Nyxo.vs Save] Could not encode settings.")
        return false
    end
    if not force and canonicalJSON == _lastSavedJSON and not _nyxoHubSaveState.dirty then
        return true
    end
    _nyxoHubSaveState.dirty = true

    if _nyxoHubSaveState.writing then
        scheduleNYXOHUBSave(0.25)
        return true
    end
    if not force and _tick() - _nyxoHubSaveState.lastAt < 0.25 then
        scheduleNYXOHUBSave(0.25)
        return true
    end

    local readFn, writeFn = resolveNYXOHUBFileApi()
    if not readFn or not writeFn then
        warn("[Nyxo.vs Save] Executor file API is unavailable.")
        scheduleNYXOHUBSave(1)
        return false
    end

    _nyxoHubSaveState.writing = true
    _nyxoHubSaveState.revision = _nyxoHubSaveState.revision + 1
    local writeConfig = config
    writeConfig.revision = _nyxoHubSaveState.revision
    writeConfig.savedAt = os.time()
    local json = HS:JSONEncode(writeConfig)
    local ok = false

    for attempt = 1, 3 do
        local attemptOk = pcall(function()
            if nyxoHubFileExists(CONFIG_FILE) then
                local previous = readFn(CONFIG_FILE)
                if type(previous) == "string" then writeFn(CONFIG_FILE .. ".backup", previous) end
            end
            writeFn(CONFIG_FILE, json)
            local readBack = readFn(CONFIG_FILE)
            if readBack ~= json then error("save verification failed") end
            HS:JSONDecode(readBack)
        end)
        if attemptOk then
            ok = true
            break
        end
        if attempt < 3 then task.wait(0.1 * attempt) end
    end

    _nyxoHubSaveState.writing = false
    if ok then
        _nyxoHubSaveState.lastAt = _tick()
        _nyxoHubSaveState.retryCount = 0
        _lastSavedJSON = canonicalJSON
        _nyxoHubSaveState.dirty = false
        local latestOk, latest = pcall(function()
            local latestConfig = buildConfigTable()
            latestConfig.configVersion = 2
            latestConfig.userId = LP.UserId
            return HS:JSONEncode(latestConfig)
        end)
        if not latestOk or latest ~= _lastSavedJSON then
            _nyxoHubSaveState.dirty = true
            scheduleNYXOHUBSave(0.25)
        end
    else
        _nyxoHubSaveState.retryCount = _nyxoHubSaveState.retryCount + 1
        warn("[Nyxo.vs Save] Write or verification failed; will retry.")
        scheduleNYXOHUBSave(math.min(2, 0.5 * _nyxoHubSaveState.retryCount))
    end
    return ok
end

