        local bindBtn = Instance.new("TextButton", row)
        bindBtn.Size             = UDim2.new(0,72,0,24)
        bindBtn.Position         = UDim2.new(1,-88,0.5,-12)
        bindBtn.BackgroundColor3 = C.inputBg
